import{_ as t,c as e,o as r,ag as a}from"./chunks/framework.DPDPlp3K.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"shopify/storefronts/robots.txt/index.md","filePath":"shopify/storefronts/robots.txt/index.md"}'),i={name:"shopify/storefronts/robots.txt/index.md"};function l(s,o,n,p,h,f){return r(),e("div",null,o[0]||(o[0]=[a('<h2 id="标题备选" tabindex="-1">标题备选 <a class="header-anchor" href="#标题备选" aria-label="Permalink to &quot;标题备选&quot;">​</a></h2><ol><li>Shopify 开发实战：Shopify robots.txt 自定义 一篇讲清楚</li><li>手把手梳理 Shopify：Shopify robots.txt 自定义 的关键用法和避坑点</li><li>做 Shopify 项目别只会改主题，这篇带你搞懂 Shopify robots.txt 自定义</li></ol><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>这篇文章适合 Shopify 主题和应用开发者，围绕「Shopify robots.txt 自定义」梳理核心概念、配置路径和实战注意点，方便项目中快速对照。</p><h2 id="正文" tabindex="-1">正文 <a class="header-anchor" href="#正文" aria-label="Permalink to &quot;正文&quot;">​</a></h2><p>哈喽大家好👋 我是程序🦍kk。把复杂知识掰成大白话讲明白，是我一直以来的小追求✨；<strong>打好基础才能稳步进阶</strong>，是我始终秉持的学习理念～</p><blockquote><p>📢 我搭建了5000人程序猿专属学习交流群 群内会同步前端开发/全栈开发/Web3开发/远程工作等干货资源 关注我并回复 <strong>加群</strong> ，就能加入交流圈啦🚀</p></blockquote><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><strong>Shopify 项目最容易卡住的地方，往往不是“会不会写代码”，而是主题、应用和后台配置之间的关系没理顺。</strong></p><p>很多同学做 Shopify 开发时，会同时碰到 Liquid、主题目录、Checkout、Metafields、应用后台、性能优化这些概念。单独看不难，放到真实项目里就容易散。</p><p>这篇围绕「Shopify robots.txt 自定义」把原始笔记整理成更适合阅读和复用的版本，适合做主题开发、应用开发或者接手 Shopify 项目时快速对照。</p><h2 id="shopify-实战整理" tabindex="-1">Shopify 实战整理 <a class="header-anchor" href="#shopify-实战整理" aria-label="Permalink to &quot;Shopify 实战整理&quot;">​</a></h2><p>下面进入 Shopify 相关内容整理。建议大家边看边对照自己的店铺、主题代码和应用后台，很多问题只有放到真实配置里才容易看清楚。</p><p>如果你正在做 Shopify 项目，可以重点留意主题代码、后台配置、应用能力和官方限制之间的边界，很多线上问题都出在这些交界处。</p><p>参考：<a href="https://help.shopify.com/en/manual/promoting-marketing/seo/editing-robots-txt" target="_blank" rel="noreferrer">https://help.shopify.com/en/manual/promoting-marketing/seo/editing-robots-txt</a></p><hr><p>GMC = Google Merchant Center。它是 Google 的商家平台，用来上传/管理商品数据并在 Google 购物、广告等渠道展示。 在你前面的 robots.txt 场景下，GMC 需要能抓取商品和相关资源（商品页、图片、结构化数据）。如果被 robots.txt 阻挡，会在 GMC 诊断里看到“被 robots.txt 阻止”。处理要点：</p><ul><li>确保允许 Googlebot 和 Googlebot-image 抓取商品页、图片资源；通常 Disallow: 为空即全放行。</li><li>保存 robots.txt 后，在浏览器访问 <a href="https://xn--6qqv7i2xdt95b/robots.txt" target="_blank" rel="noreferrer">https://你的域名/robots.txt</a> 验证，再在 GMC 的“测试 robots.txt”或“抓取诊断”里重新测试。</li><li>若诊断列出具体被挡的 URL，把对应路径用 Allow: 放开（不要放开 /admin、/checkout 等敏感路径）。</li></ul><hr><ul><li>User-agent: Googlebot 指定下面的规则作用于 Google 的网页抓取机器人。</li><li>Disallow: 空值表示“无禁止路径”，即对该 user-agent 完全允许抓取所有路径（等价于 Allow: /）。</li><li>User-agent: Googlebot-image 指定下面的规则作用于 Google 的图片抓取机器人。</li><li>紧随的 Disallow: 同样为空，含义是对图片爬虫不做限制，允许抓取所有路径。</li></ul><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>好啦，今天的分享就到这里！</p><p>💬 互动时间：</p><p>你现在做 Shopify 更常遇到的是主题开发、Checkout 定制、应用接入，还是性能优化？如果你在「Shopify robots.txt 自定义」上踩过坑，也可以把场景留言出来。</p><p>最后，感谢你看到这里👏</p><p>如果喜欢这篇内容，不妨顺手给小编安排一波👇 <strong>点赞</strong>👍｜<strong>转发</strong>📲｜<strong>推荐</strong>❤️｜<strong>评论</strong>📣</p><p>要是想第一时间蹲到新内容推送，记得给我点个<strong>星标</strong>⭐️</p><p>更多干货内容正在持续填坑中，咱们下期见👋</p><h2 id="标签建议" tabindex="-1">标签建议 <a class="header-anchor" href="#标签建议" aria-label="Permalink to &quot;标签建议&quot;">​</a></h2><p>Shopify、主题开发、独立站</p>',30)]))}const g=t(i,[["render",l]]);export{d as __pageData,g as default};
